CREATE TABLE IF NOT EXISTS link_connect_attempts (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), oauth_state_hash text UNIQUE, browser_binding_hash text, code_verifier_enc text, expires_at timestamptz NOT NULL, started_at timestamptz);
CREATE TABLE IF NOT EXISTS link_connections (user_id uuid PRIMARY KEY REFERENCES users(id), link_user_id text, email text, scope text NOT NULL, access_token_enc text NOT NULL, access_expires_at timestamptz NOT NULL, refresh_token_enc text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS link_spend_requests (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), credential_type text NOT NULL, amount bigint NOT NULL, currency text NOT NULL, merchant_name text, merchant_url text, merchant_account_id text, context text NOT NULL, test boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS link_spend_requests_user ON link_spend_requests(user_id,created_at DESC);
